html:
{%- set company = frappe.get_doc("Company", doc.company) -%}
{%- set customer = frappe.get_doc("Customer", doc.customer) -%}

{# MODIFIED FIX: Only ensure item_code is present, which is sufficient for Pick List data. #}
{% set all_locations_list = [] %}
{% for location in doc.locations %}
    {% if location.item_code %}
        {% set all_locations_list = all_locations_list + [location] %}
    {% endif %}
{% endfor %}

{# Use the filtered list for pagination logic #}
{% set chunk_size = 8 %}
{% set total_items = all_locations_list | length %}
{% set chunks = (total_items // chunk_size) + (1 if total_items % chunk_size else 0) %}

{% set all_locations = all_locations_list %}  {# Assign the filtered list to the original variable name #}

<style>
 @page {
  margin: 5mm;   /* shrink print page margins */
}
body, .print-format {
  margin: 0;
  padding: 0;
  font-family: Arial, sans-serif;
  font-size: 9pt;
}
.wrapper {
  width: 100%;
  padding: 4px;
  border: 1px solid #000;
  box-sizing: border-box;
}

/* Header */
.header { 
    display:flex; 
    flex-direction:column; 
    border-bottom:1px solid #000; 
    padding:6px; 
    position: relative;
}
.company-block { width:65%; }
.company-name { font-weight:bold; font-size:11pt; }
.company-details { font-size:10pt; line-height:1.2; }

.page-info {
    position: absolute;
    top: 8px;
    right: 8px;
    font-size: 9pt;
    font-weight: bold;
    color: #444;
}


/* Customer/Pick List Info */
.info { border-bottom:1px solid #000; display:flex; font-size:10pt; }
.info-left, .info-right { width:50%; padding:6px; }
.info-left { border-right:1px solid #000; }
.info-label { font-weight:bold; width:110px; display:inline-block; }
.address-text {
    min-height: 40px;
    line-height: 1.3;
}


/* Items Table */
table.items { 
    width:100%; 
    border-collapse:collapse; 
    font-size:10pt;
    table-layout: fixed;
}
.items th {
  border:1px solid #000; padding:4px; background:#f5f5f5;
  text-align:center; font-weight:bold; font-size:10pt;
}

/* MODIFIED: Set new widths for Pick List columns (Removed Rate, Tax, Amount, Added Sales Order) */
.items th:nth-child(1), .items td:nth-child(1) { width: 5%; }    /* Sl No */
.items th:nth-child(2), .items td:nth-child(2) { width: 30%; }   /* Product Code */
.items th:nth-child(3), .items td:nth-child(3) { width: 30%; }   /* Description */
.items th:nth-child(4), .items td:nth-child(4) { width: 10%; }   /* Qty to Pick */
.items th:nth-child(5), .items td:nth-child(5) { width: 10%; }   /* Warehouse */
.items th:nth-child(6), .items td:nth-child(6) { width: 15%; }   /* Sales Order Ref */

/* Ensure item row borders/text formatting remain clean */
.items td {
  padding:4px;
  border:1px solid #000;
  border-bottom:1px dotted #000;
  word-wrap: break-word;
}

.items td:last-child { border-right:1px solid #000; }
.items tr:last-child td { border-bottom:1px solid #000; }
.text-center { text-align:center; }
.text-right { text-align:right; }

/* CSS for empty rows to remove horizontal lines */
.empty-row td {
    height: 18px;
    border-top: none;
    border-bottom: none;
    border-right: 1px solid #000;
}
.empty-row td:first-child { border-left: 1px solid #000; }
.empty-row td:last-child { border-right: 1px solid #000; }


/* Pick List Summary & Footer Section - MODIFIED TO LOGISTICS */
.logistics-summary { 
    display:flex; 
    font-size:10pt; 
    min-height: 110px;
}

/* This takes the space where Totals and Bank/Tax details were */
.logistics-notes { 
    width:70%; 
    padding:6px; 
    border-right:1px solid #000; 
    border-left:1px solid #000; 
    display:flex; 
    flex-direction:column;
    justify-content:space-between;
}
.logistics-summary-right { 
    width:30%; 
    padding:6px; 
    border-right:1px solid #000; 
    text-align:center; 
    display:flex; 
    flex-direction:column; 
    justify-content:space-between;
    border-left:1px solid #000; /* Add border for right-side block */
}


/* Footer - COMBINED/SIMPLIFIED */
.footer { 
    border-top: 1px solid #000; 
    display:flex; 
    font-size:10pt; 
    padding:6px; 
    align-items:flex-start;
}

.page-break { page-break-before: always; }
</style>

{% for page in range(chunks) %}
<div class="wrapper">

  <!-- Header -->
<div class="header">

    <!-- Page number added here -->
    <div class="page-info">
        Page {{ page + 1 }} of {{ chunks }}
    </div>

    <!-- Top Row: Logo + Company Info -->
    <div style="display:flex; justify-content:space-between; align-items:center; width:100%; margin-bottom:8px;">
        <div class="logo" style="width:127px; height:115px;">
            <img src="/files/Dacs inc Logo.jpeg" alt="Company Logo" style="max-width:100%; max-height:100%; object-fit:contain;">
        </div>
        <div class="company-block" style="flex-grow:1; padding-left:10px;">
            <div class="company-name" style="font-weight:bold; font-size:12pt;">{{ company.name }}</div>
            <div class="company-details" style="font-size:10pt; line-height:1.3;">
                Jaya Sai Towers No.40, 1st & 2nd floor, Sajjan Rao Road, Parvathipuram,<br>
                V.V.Puram, BANGALORE - 560004, Karnataka, India<br>
                GSTIN/UIN: 29AAIFD5710C1ZQ<br>
                Phone: 080-41234140, 080-41206892 | Email: accounts@dacsinc.in<br>
                Web: www.dacsinc.in
            </div>
        </div>
    </div>

    <!-- Bottom Row: Pick List Info -->
    <div style="text-align:center; border-top:1px solid #000; padding-top:6px; font-size:12pt;">
        <div style="font-weight:bold; font-size:14pt; margin-bottom:4px;">PICK LIST</div>
        <div>No: {{ doc.name }} | Date: {{ doc.get_formatted('posting_date') }}</div>
    </div>
</div>

  <!-- Customer / Pick List Info -->
  <div class="info">
    <div class="info-left">
      <div><strong>To Customer M/s. {{ doc.customer_name or "N/A" }}</strong></div>
      <div class="address-text">{{ doc.shipping_address or doc.address_display or "No address provided for Shipping/Billing." }}</div>
      <div><span class="info-label">GST No</span>: {{ customer.gstin or "N/A" }}</div>
      <div><span class="info-label">Phone</span>: {{ doc.contact_mobile or "N/A" }}</div>
    </div>
    <div class="info-right">
      {# CHANGED: Use fields more relevant to logistics #}
      <div><span class="info-label">Sales Order</span>: {{ doc.sales_order or "-" }}</div>
      <div><span class="info-label">Pick List Status</span>: {{ doc.status or "Draft" }}</div>
      <div><span class="info-label">Source Warehouse</span>: {{ doc.warehouse or "N/A" }}</div>
      <div><span class="info-label">Created By</span>: {{ doc.owner_name or "-" }}</div>
    </div>
  </div>

  <!-- Items - MODIFIED COLUMNS -->
  <table class="items">
    <thead>
      <tr>
        <th>Sl No</th>
        <th>Product Code & Product Name</th>
        <th>Description</th>
        <th style="font-size: 9pt;">Qty to Pick</th>
        <th>Source Warehouse</th>
        <th>Sales Order Ref</th>
      </tr>
    </thead>
    <tbody>
      {# Logic to ensure a fixed number of rows #}
      {% set start = page * chunk_size %}
      {% set end = (page + 1) * chunk_size %}

      {# Iterate over all_locations filtered list #}
      {% set items_on_page = all_locations[start:end] %} 

      {# Loop 1: Render the actual item rows for the current page #}
      {% for item in items_on_page %}
      <tr>
        <td class="text-center">{{ loop.index + start }}</td>
        <td>{{ item.item_code }} - {{ item.item_name }}</td>
        <td>{{ item.description or "" }}</td>
        <td class="text-center"><b>{{ item.qty or 0 }}</b></td> {# Qty #}
        <td class="text-center">{{ item.warehouse or "" }}</td>
        <td class="text-center">{{ item.sales_order or "N/A" }}</td> {# Sales Order Ref #}
      </tr>
      {% endfor %}

      {# Loop 2: Render empty rows to fill the remaining space up to chunk_size #}
      {% if (items_on_page|length) < chunk_size %}
        {% for i in range((items_on_page|length), chunk_size) %}
        <tr class="empty-row">
          <td>&nbsp;</td>
          <td>&nbsp;</td>
          <td>&nbsp;</td>
          <td>&nbsp;</td>
          <td>&nbsp;</td>
          <td>&nbsp;</td>
        </tr>
        {% endfor %}
      {% endif %}
    </tbody>
  </table>

  {# Show Summary/Notes/Signatures only on last page #}
  {% if page + 1 == chunks %}

    <!-- MODIFIED: LOGISTICS SUMMARY & SIGNATURE -->
    <div class="logistics-summary">
        <div class="logistics-notes" style="border-bottom: 1px solid #000;">
            <strong>Picking Notes/Instructions:</strong>
            <div style="line-height:1.4; padding-top:4px;">
                {{ doc.instructions or doc.remarks or "Standard Picking Procedure. Ensure items are accurately counted and verified against the Sales Order." }}
            </div>
            <div style="margin-top: 10px;">
                <span style="font-weight:bold;">Total Units: </span> {{ all_locations | sum(attribute='qty') | round(2) or 0 }} units requested.
            </div>
        </div>
        <div class="logistics-summary-right" style="border-right: 1px solid #000; border-bottom: 1px solid #000; border-left: none;">
            <div>
                <strong>FOR STORE/WAREHOUSE USE ONLY</strong>
            </div>
            <div>
                <div style="border-bottom:1px solid #000; width:90%; margin:0 auto 10px auto;"></div>
                Store/Picked By Signature
            </div>
            <div>
                <div style="border-bottom:1px solid #000; width:90%; margin:0 auto 10px auto;"></div>
                Packing Verified By
            </div>
        </div>
    </div>

    {# MODIFIED: Footer area for delivery/signature #}
    <div class="footer">
        <div class="footer-left" style="width:50%; border-left:1px solid #000; padding-right:10px;">
             <strong>Receiving Confirmation:</strong><br>
             I confirm receipt of the above materials in good condition.
        </div>
        <div class="footer-right" style="width:50%; text-align:right; border-right:1px solid #000; border-left:1px solid #000;">
             <div style="width:70%; float:right; text-align:center;">
                 <br><br><br>
                 <div style="border-bottom:1px solid #000; width:80%; margin:0 auto;"></div>
                 Receiver's Name / Signature
             </div>
        </div>
    </div>

  {% endif %}

</div>

{% if not loop.last %}
<div class="page-break"></div>
{% endif %}
{% endfor %}
